"""Depth table: verifies n_ell = v2((ell^2-1)/8) equals v2(ell-1)+v2(ell+1)-3."""
from __future__ import annotations
from typing import List


def v2(n: int) -> int:
    c = 0
    while n % 2 == 0:
        n //= 2
        c += 1
    return c


def n_ell(ell: int) -> int:
    return v2((ell * ell - 1) // 8)


def n_ell_closed(ell: int) -> int:
    return v2(ell - 1) + v2(ell + 1) - 3


def main() -> None:
    primes: List[int] = [3, 5, 7, 17, 31, 97, 127, 257, 8191]
    for ell in primes:
        assert (ell * ell - 1) % 8 == 0
        assert n_ell(ell) == n_ell_closed(ell)
        print(f"ell={ell:>6}  n_ell={n_ell(ell)}  (closed form matches)")


if __name__ == "__main__":
    main()

"""Additivity of the global invariant over coprime twisting parameters."""
from __future__ import annotations
from math import gcd
from typing import Callable, List


def v2(n: int) -> int:
    c = 0
    while n % 2 == 0:
        n //= 2
        c += 1
    return c


def prime_factors(n: int) -> List[int]:
    out: List[int] = []
    d, m = 2, n
    while d * d <= m:
        if m % d == 0:
            out.append(d)
            while m % d == 0:
                m //= d
        d += 1
    if m > 1:
        out.append(m)
    return out


def local_term(ell: int, conductor: int, order: Callable[[int], int]) -> int:
    depth = v2((ell * ell - 1) // 8)
    if conductor % ell == 0:
        return 2 ** depth
    if order(ell) % 2 == 0:
        return 2 ** (depth + 1)
    return 0


def lambda_diff(D: int, conductor: int, order: Callable[[int], int]) -> int:
    return sum(local_term(ell, conductor, order) for ell in prime_factors(D))


def main() -> None:
    conductor = 21
    order = lambda ell: ell + 1
    for a, b in [(5, 11), (13, 17), (3, 55), (7, 101)]:
        assert gcd(a, b) == 1
        lhs = lambda_diff(a * b, conductor, order)
        rhs = lambda_diff(a, conductor, order) + lambda_diff(b, conductor, order)
        assert lhs == rhs
        print(f"Lambda({a}*{b}) = {lhs} = {rhs} = Lambda({a}) + Lambda({b})")


if __name__ == "__main__":
    main()

"""Monotonicity of the global invariant across the divisor lattice of a level."""
from __future__ import annotations
from typing import Callable, List


def v2(n: int) -> int:
    c = 0
    while n % 2 == 0:
        n //= 2
        c += 1
    return c


def prime_factors(n: int) -> List[int]:
    out: List[int] = []
    d, m = 2, n
    while d * d <= m:
        if m % d == 0:
            out.append(d)
            while m % d == 0:
                m //= d
        d += 1
    if m > 1:
        out.append(m)
    return out


def local_term(ell: int, conductor: int, order: Callable[[int], int]) -> int:
    depth = v2((ell * ell - 1) // 8)
    if conductor % ell == 0:
        return 2 ** depth
    if order(ell) % 2 == 0:
        return 2 ** (depth + 1)
    return 0


def lambda_diff(D: int, conductor: int, order: Callable[[int], int]) -> int:
    if D == 1:
        return 0
    return sum(local_term(ell, conductor, order) for ell in prime_factors(D))


def main() -> None:
    conductor, order = 10, (lambda ell: ell - 1)
    D = 3 * 5 * 7 * 11
    divisors: List[int] = [d for d in range(1, D + 1) if D % d == 0]
    top = lambda_diff(D, conductor, order)
    for d in divisors:
        assert lambda_diff(d, conductor, order) <= top
    print(f"Lambda(D) = {top}; every divisor d | D satisfies Lambda(d) <= Lambda(D).")


if __name__ == "__main__":
    main()

